              </span>
              <el-tag v-if="isOverdue(row)" type="danger" size="small" effect="plain" class="overdue-tag">已逾期</el-tag>
            </template>
          </el-table-column>
          <el-table-column label="状态" width="100">
            <template #default="{ row }">
              <el-tag :type="getStatusType(row)" effect="light" class="status-tag">
