              </el-tag>
            </template>
          </el-table-column>
          <el-table-column prop="purpose" label="用途" min-width="160" show-overflow-tooltip />
          <el-table-column label="操作" fixed="right" width="120">
            <template #default="{ row }">
              <el-button 
                v-if="row.status === 'approved' && activeApps.find(a => a.code === 'borrow')?.requires_manual_return"
                size="small" 
                type="success" 
                link
                class="action-btn"
