    <el-dialog v-model="borrowDialogVisible" title="新借用登记" width="520px" class="feishu-dialog" destroy-on-close>
      <el-form :model="borrowForm" label-width="100px" ref="borrowFormRef" :rules="borrowRules" class="feishu-form">
