            <el-option
              v-for="item in availableEquipments"
              :key="item.id"
              :label="`${item.name} (${item.code})`"
              :value="item.id"
            />
          </el-select>
        </el-form-item>
        <el-form-item label="预计归还" prop="expected_return_date">
