          <el-select v-model="borrowForm.approver" placeholder="请选择审核老师" style="width: 100%" filterable>
            <el-option
              v-for="user in approverUsers"
              :key="user.id"
              :label="`${user.name}（${user.role || '审批人'}）`"
              :value="user.id"
            />
          </el-select>
        </el-form-item>
