    <el-dialog v-model="returnDialogVisible" title="设备归还登记" width="440px" class="feishu-dialog" destroy-on-close>
      <div class="return-info-card" v-if="selectedBorrow">
        <div class="info-item">
          <span class="info-label">设备</span>
          <span class="info-value">{{ selectedBorrow.equipment_name }}</span>
        </div>
        <div class="info-item">
          <span class="info-label">借用人</span>
          <span class="info-value">{{ selectedBorrow.borrower_name }}</span>
        </div>
      </div>
      <el-form :model="returnForm" label-width="90px" class="feishu-form">
        <el-form-item label="设备状态">
          <el-radio-group v-model="returnForm.return_condition" class="condition-radio">
            <el-radio label="良好">
              <span class="radio-option">良好</span>
