<script setup>
import { ref, onMounted, reactive, computed } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { Box, Plus } from '@element-plus/icons-vue'
import api from '@/api'
import dayjs from 'dayjs'

const router = useRouter()
const borrows = ref([])
const availableEquipments = ref([])
const approverUsers = ref([])
const currentUser = ref(JSON.parse(localStorage.getItem('user') || 'null'))
const filterStatus = ref('borrowed')
const borrowDialogVisible = ref(false)
const returnDialogVisible = ref(false)
const selectedBorrow = ref(null)
const borrowFormRef = ref(null)
const activeApps = ref([])
const meta = ref({ instance_statuses: [], apps: [] })

const instanceStatusLabelMap = computed(() => {
  const m = {}
  for (const s of (meta.value.instance_statuses || [])) {
    if (s && s.code) m[s.code] = s.label
  }
  return m
})

const borrowForm = reactive({
  equipment: '',
  approver: '',
  expected_return_date: '',
  purpose: ''
})

const returnForm = reactive({
  return_condition: '良好',
  return_notes: ''
})

const borrowRules = {
  equipment: [{ required: true, message: '请选择设备', trigger: 'change' }],
  approver: [{ required: true, message: '请选择审核老师', trigger: 'change' }],
  expected_return_date: [{ required: true, message: '请选择预计归还时间', trigger: 'change' }],
  purpose: [{ required: true, message: '请输入用途', trigger: 'blur' }]
}

const fetchApproverUsers = async () => {
  try {
    const res = await api.getUsers({ role: 'teacher' })
    console.log('[Borrows] getUsers raw response:', res)
    console.log('[Borrows] res.data:', res?.data)
    console.log('[Borrows] res.data.results:', res?.data?.results)
    const list = res.data?.results ?? res.data ?? []
    console.log('[Borrows] parsed list:', list)
    approverUsers.value = list
  } catch (e) {
    console.error('[Borrows] 加载审批老师失败', e)
    approverUsers.value = []
  }
}

const fetchBorrows = async () => {
  try {
    const statusMap = {
      all: '',
      pending: 'pending',
      borrowed: 'approved',
      returned: 'completed'
    }
    const status = statusMap[filterStatus.value] ?? ''
    const [res, eqRes] = await Promise.all([
      api.getLowCodeInstances('borrow', null, status),
      api.getEquipments()
    ])
    const rawData = res.data.results || res.data || []
    const eqList = eqRes.data?.results || eqRes.data || []
    const eqMap = new Map(eqList.map(eq => [Number(eq.id), eq]))
    
    borrows.value = rawData.map(inst => ({
      id: inst.id,
      equipment_name: (() => {
        const eqId = inst.data?.equipment_id
        const eq = eqMap.get(Number(eqId))
        return eq?.name || inst.data?.equipment_name || '未知设备'
      })(),
      equipment_id: inst.data?.equipment_id,
      borrower_name: inst.applicant_name,
      borrow_date: inst.created_at,
      expected_return_date: inst.data?.expected_return_date,
      status: inst.status,
      purpose: inst.data?.purpose || inst.data?.content || '',
      raw: inst
    }))
  } catch (error) {
    ElMessage.error('获取借用记录失败')
  }
}

const fetchAvailableEquipments = async () => {
  try {
    const res = await api.getEquipments({ status: 'available' })
    availableEquipments.value = res.data.results || res.data || []
  } catch (error) {
    console.error('获取可用设备失败')
  }
}

const fetchActiveApps = async () => {
  try {
    const res = await api.getLowCodeApps()
    activeApps.value = res.data || []
  } catch (error) {
    console.error('获取应用列表失败')
  }
}

const handleNewBorrow = () => {
  console.log('[Borrows] handleNewBorrow 被调用了')
  Object.assign(borrowForm, {
    equipment: '',
    approver: '',
    expected_return_date: '',
    purpose: ''
  })
  fetchAvailableEquipments()
  fetchApproverUsers()
  borrowDialogVisible.value = true
}

const submitBorrow = async () => {
  if (!borrowFormRef.value) return
  await borrowFormRef.value.validate(async (valid) => {
    if (!valid) return
    const uid = currentUser.value?.id
    if (!uid) {
      ElMessage.error('请先登录')
      return
    }
    try {
      const ret = dayjs(borrowForm.expected_return_date)
      const borrowDays = Math.max(1, Math.ceil(ret.diff(dayjs(), 'day', true)))
      await api.createLowCodeInstance({
        app_code: 'borrow',
        form_data: {
          equipment_id: borrowForm.equipment,
          borrow_days: borrowDays,
          expected_return_date: ret.format('YYYY-MM-DD'),
          approver_id: borrowForm.approver,
          purpose: borrowForm.purpose
        },
        user_id: uid
      })
      ElMessage.success('提交成功，等待老师审批')
      borrowDialogVisible.value = false
      fetchBorrows()
    } catch (error) {
      ElMessage.error(api.getErrorMessage(error, '借用登记失败'))
    }
  })
}

const formatDate = (date) => {
  return date ? dayjs(date).format('YYYY-MM-DD HH:mm') : '-'
}

const isOverdue = (row) => {
  if (row.status !== 'approved') return false
  return dayjs().isAfter(dayjs(row.expected_return_date))
}

const getStatusText = (row) => {
  if (row.status === 'approved') return '借用中'
  if (row.status === 'completed') return '已归还'
  return instanceStatusLabelMap.value[row.status] || row.status
}

const getStatusType = (row) => {
  const map = {
    pending: 'warning',
    approved: 'success',
    completed: 'info',
    rejected: 'danger'
  }
  return map[row.status] || 'info'
}

const handleReturn = (row) => {
  selectedBorrow.value = row
  returnForm.return_condition = '良好'
  returnForm.return_notes = ''
  returnDialogVisible.value = true
}

const submitReturn = async () => {
  try {
    await api.returnLowCodeInstance({
      instance_id: selectedBorrow.value.id,
      user_id: null,
      return_info: returnForm
    })
    ElMessage.success('设备已成功归还入库')
    returnDialogVisible.value = false
    fetchBorrows()
  } catch (error) {
    ElMessage.error(api.getErrorMessage(error, '归还操作失败'))
  }
}

onMounted(() => {
  api.getMeta().then(r => { meta.value = r.data || {} }).catch(() => {})
  fetchActiveApps()
  fetchBorrows()
})
</script>

